#include "ama10.h"
#include "ama10_imggen.h"
#include "checkpoint.h"
#include "tokenizer.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
static char*suffix(const char*p,const char*s){size_t a=strlen(p),b=strlen(s);char*q=(char*)malloc(a+b+1);if(q){memcpy(q,p,a);memcpy(q+a,s,b+1);}return q;}
static uint64_t rng(uint64_t*x){*x^=*x>>12;*x^=*x<<25;*x^=*x>>27;return *x*UINT64_C(2685821657736338717);}
static int parse_size(const char*s,size_t*out){if(!s||!*s)return 0;size_t n=0;for(const unsigned char*p=(const unsigned char*)s;*p;p++){if(*p<'0'||*p>'9')return 0;unsigned d=*p-'0';if(n>(SIZE_MAX-d)/10)return 0;n=n*10+d;}if(!n)return 0;*out=n;return 1;}
static uint32_t coord_token(size_t axis,size_t value,size_t codes){size_t base=256+codes+(axis?8:0);return (uint32_t)(base+value);}
static size_t normalized_coord(size_t position,size_t extent){return extent<2?0:(size_t)llround(7.0*(double)position/(double)(extent-1));}
static int parse_seed(const char*s,uint64_t*out){if(!s||!*s)return 0;uint64_t n=0;for(const unsigned char*p=(const unsigned char*)s;*p;p++){if(*p<'0'||*p>'9')return 0;unsigned d=*p-'0';if(n>(UINT64_MAX-d)/10)return 0;n=n*10+d;}*out=n;return 1;}
int main(int argc,char**argv){if(argc<4||argc>9){fprintf(stderr,"usage: %s <checkpoint.ama> <prompt.txt> <output.ppm> [language=en] [temperature=0.8] [width=64] [height=64] [seed=1]\n",argv[0]);return 2;}
 const char*lang=argc>=5?argv[4]:"en";double temp=0.8;size_t width=64,height=64;uint64_t random_seed=1;if(argc>=6){char*end=NULL;temp=strtod(argv[5],&end);if(end==argv[5]||*end||!isfinite(temp)||temp<0.05||temp>5.0)return 2;}if(argc>=7&&!parse_size(argv[6],&width))return 2;if(argc>=8&&!parse_size(argv[7],&height))return 2;if(argc>=9&&!parse_seed(argv[8],&random_seed))return 2;if(strlen(lang)>8)return 2;FILE*f=fopen(argv[2],"rb");if(!f)return 1;if(fseek(f,0,SEEK_END)){fclose(f);return 1;}long z=ftell(f);if(z<1||z>4096||fseek(f,0,SEEK_SET)){fclose(f);return 1;}unsigned char*text=(unsigned char*)malloc((size_t)z+1);if(!text){fclose(f);return 1;}int good=fread(text,1,(size_t)z,f)==(size_t)z&&fclose(f)==0;if(!good){free(text);return 1;}while(z>0&&(text[z-1]=='\n'||text[z-1]=='\r'))z--;if(!z){free(text);return 1;}
 AMA10Model m={0};AMA10Tokenizer tok={0};AMA10Optimizer opt={0};AMA10State st={0};AMA10CheckpointProgress pr={0};AMA10ImageCodebook book={0};uint32_t*ids=NULL,*codes=NULL;size_t ni=0,ncodes=0;float*logits=NULL;AMA10Image im={0};char*vp=suffix(argv[1],".vq");int ok=vp&&ama10_checkpoint_load(argv[1],&m,&tok,&opt,&st,&pr)&&ama10_image_codebook_load(&book,vp)&&book.code_count<255&&tok.vocabulary_size==273+book.code_count&&m.vocabulary==tok.vocabulary_size;free(vp);if(!ok)goto done;
 char prefix[32];int pn=snprintf(prefix,sizeof(prefix),"<lang:%s> ",lang);size_t total=(size_t)pn+(size_t)z+2;unsigned char*b=(unsigned char*)malloc(total);if(!b)goto done;memcpy(b,prefix,(size_t)pn);memcpy(b+pn,text,(size_t)z);b[pn+z]='\n';b[pn+z+1]=0;ok=ama10_tokenizer_encode(&tok,b,total,&ids,&ni);free(b);if(!ok)goto done;
 size_t dx=width>book.patch_width?width-book.patch_width:0,dy=height>book.patch_height?height-book.patch_height:0;size_t grid_w=dx/book.stride_width+(dx%book.stride_width!=0)+1,grid_h=dy/book.stride_height+(dy%book.stride_height!=0)+1;if(grid_w>SIZE_MAX/grid_h)goto done;ncodes=grid_w*grid_h;if(!ncodes||ncodes>SIZE_MAX/sizeof(*codes))goto done;codes=(uint32_t*)malloc(ncodes*sizeof(*codes));logits=(float*)malloc(m.vocabulary*sizeof(float));if(!logits||!codes)goto done;ama10_state_reset(&st);for(size_t i=0;i<ni;i++)if(!ama10_step(&m,&st,ids[i],logits,2,2.0f)){ok=0;goto done;}
 uint64_t random_state=random_seed;if(!random_state)random_state=UINT64_C(0x9e3779b97f4a7c15);
 const uint32_t image_base=256;
 for(size_t p=0;p<ncodes;p++){size_t px=p%grid_w,py=p/grid_w;uint32_t yt=coord_token(1,normalized_coord(py,grid_h),book.code_count),xt=coord_token(0,normalized_coord(px,grid_w),book.code_count);if(!ama10_step(&m,&st,yt,logits,2,2.0f)||!ama10_step(&m,&st,xt,logits,2,2.0f)){ok=0;goto done;}float maximum=logits[image_base];for(uint32_t c=1;c<book.code_count;c++)if(logits[image_base+c]>maximum)maximum=logits[image_base+c];double total=0;for(uint32_t c=0;c<book.code_count;c++)total+=exp(((double)logits[image_base+c]-maximum)/temp);double draw=(double)(rng(&random_state)>>11)*(1.0/9007199254740992.0)*total;uint32_t selected=book.code_count-1;for(uint32_t c=0;c<book.code_count;c++){draw-=exp(((double)logits[image_base+c]-maximum)/temp);if(draw<=0){selected=c;break;}}codes[p]=selected+1;uint32_t token=image_base+selected;if(!ama10_step(&m,&st,token,logits,2,2.0f)){ok=0;goto done;}}
 ok=ama10_image_decode_codes_size(&book,codes,ncodes,width,height,&im)&&ama10_image_save_ppm(&im,argv[3]);if(ok)printf("generated=%zux%zu ppm visual_codes=%zu patch=%ux%u stride=%ux%u temperature=%.2f seed=%llu checkpoint_update=%llu output=%s\n",width,height,ncodes,book.patch_width,book.patch_height,book.stride_width,book.stride_height,temp,(unsigned long long)random_seed,(unsigned long long)pr.completed_updates,argv[3]);
done:if(!ok)fprintf(stderr,"image generation failed\n");ama10_image_free(&im);free(codes);free(logits);free(ids);free(text);ama10_image_codebook_free(&book);ama10_state_free(&st);ama10_optimizer_free(&opt);ama10_model_free(&m);ama10_tokenizer_free(&tok);return ok?0:1;}
